40	export type DistEntry = Readonly<{ path: string; sha256: string; bytes: number }>;
41	
42	/**
43	 * Every file below `directory`, digested, ordered by path.
44	 *
45	 * The digest is taken over the file's bytes. It used to be taken over
46	 * `bytes.toString('binary')` — a latin1 decode, which Node then re-encoded as
47	 * UTF-8 before hashing — so any file carrying a byte at or above 0x80 was
48	 * published under sha256(UTF-8(latin1(bytes))) rather than sha256(bytes). Every
49	 * lane record this walker produced is shared by that defect, which is why the
50	 * fix is here rather than in any one driver. What the defect did *not* do is
51	 * change any comparison this walker feeds: latin1 is a bijection between bytes
52	 * and the first 256 code points and UTF-8 encoding is injective, so the
