				path: path.relative(directory, full).split(path.sep).join('/'),
				sha256: sha256(bytes),
				bytes: bytes.byteLength,
			});
		}
	};
	await walk(directory);
	return entries.sort((left, right) => (left.path < right.path ? -1 : 1));
